import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    # The preamble contains blank records and title records with one filled cell.
    for header in records:
        if sum(bool(cell.strip()) for cell in header) >= 2:
            break
    else:
        return {"columns": [], "rows": []}

    rows = list(records)
    width = max(23, len(header), max((len(row) for row in rows), default=0))

    # Reserve existing labels so generated names do not collide with them.
    reserved = {label for label in header if label.strip()}
    columns = []
    for i in range(width):
        if i < len(header) and header[i].strip():
            columns.append(header[i])
        else:
            base = f"column_{i + 1}"
            name = base
            suffix = 2
            while name in reserved:
                name = f"{base}_{suffix}"
                suffix += 1
            columns.append(name)
            reserved.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
